#[derive(Debug, Clone, Default)]
#[allow(dead_code)] // `tool_router` is read by the `#[tool_handler]`-generated dispatch, invisible to dead-code analysis (mirrors rmcp's own test pattern)
pub struct TetelServer {
    tool_router: ToolRouter<Self>,
}

#[tool_router]
impl TetelServer {
    pub fn new() -> Self {
        let mut tool_router = Self::tool_router();
        // `check`'s `#[tool(description = ...)]` above carries only a
        // placeholder — see its comment for why the macro cannot compute
        // this text itself. Patched once here, before the router is ever
        // handed to a transport, so every real caller (including
        // `list_tools`/`get_tool`) sees the generated text and nothing
        // else ever does.
        if let Some(route) = tool_router.map.get_mut("check") {
            route.attr.description = Some(std::borrow::Cow::Owned(check_description()));
        }
        Self { tool_router }
    }

    #[tool(description = "Open a path into the pending observation buffer, or search it with `grep` — the evidence a `fact` is later minted from. `workspace` is required (never defaulted); ids elsewhere are workspace-relative only.")]
    async fn look(&self, Parameters(p): Parameters<LookParams>) -> Result<CallToolResult, ErrorData> {
        let dir = open_workspace(&p.workspace)?;
        // Refused after the workspace is open, not before, so it reaches
        // `workspace::refuse` and lands in the shipped record. The CLI
        // used to refuse this in clap and this handler refused it here;
        // both were pre-choke-point, so the same refusal was invisible on
        // both surfaces. Now both take this path, with one shared reason
        // text.
        if p.lines.is_some() && p.grep.is_some() {
            return Ok(refusal(
                "look",
                &p.workspace,
                crate::workspace::refuse(&dir, "look", crate::workspace::LINES_WITH_GREP),
            ));
        }
        let req = if let Some(pattern) = p.grep {
            observe::LookRequest::Grep { pattern, root: Some(p.path) }
        } else {
            observe::LookRequest::Open { path: Some(p.path), lines: p.lines.map(|l| (l.start, l.end)) }
        };
        match observe::dispatch(&dir, req) {
            Ok(outcome) => text_result(outcome.printed),
            Err(e) => Ok(refusal("look", &p.workspace, e)),
        }
    }

    #[tool(description = "Execute a command directly (no shell) and record its combined stdout/stderr into the pending buffer. The whole output is captured verbatim and, once minted into a fact, becomes permanently unrevisable and ships into the snapshot beside the memo — so a command whose output is enormous, or contains a credential, puts that in a repository forever. A command exiting 0 also establishes nothing by exiting 0: read the output and ask whether it states your proposition or merely fails to deny it. `workspace` is required (never defaulted); ids elsewhere are workspace-relative only.")]
    async fn run(&self, Parameters(p): Parameters<RunParams>) -> Result<CallToolResult, ErrorData> {
        let dir = open_workspace(&p.workspace)?;
        match observe::run_command(&dir, &p.command) {
            Ok(outcome) => Ok(CallToolResult::structured(json!({
                "exit_code": outcome.exit_code,
                "output": outcome.printed,
            }))),
            Err(e) => Ok(refusal("run", &p.workspace, e)),
        }
    }

/// observation keyed on the whole `sed` command line never overlapped
/// another range of the same file); giving `look` a first-class
/// `--lines` removes the reason to reach for `run` here at all, and its
/// key is the resolved path regardless of the range requested, so two
/// different ranges of one file always overlap each other.
///
/// A range entirely past the end of the file is not an error — it is
/// recorded as an explicit empty-range observation, the same "a bounded
/// negative must leave a trace" discipline as a zero-match grep.
pub fn look_path(workspace_dir: &Path, path: &str, lines: Option<(usize, usize)>) -> Result<LookOutcome, AuthoringError> {
    let p = Path::new(path);
    if !p.exists() {
        return Err(workspace::refuse(workspace_dir, "look", format!("no such path: {path}")));
    }
    if p.is_dir() {
        return Err(workspace::refuse(
            workspace_dir,
            "look",
            format!(
                "{path} is a directory; `tetel look` opens files. Use `tetel look --grep <pattern> {path}` to search it."
            ),
        ));
    }
    let contents = fs::read_to_string(p).map_err(|e| AuthoringError::Io(e.to_string()))?;
    let key = resolve_key(p);
    // Resolved from the file being read, never from this process's working
    // directory — see `worldstate.rs` for the measurement that forced this.
    let world = worldstate::Session::new().for_path(p);

    let (shown, label) = match lines {
        None => (contents.clone(), path.to_string()),
        Some((a, b)) => {
            if a < 1 || a > b {
                return Err(workspace::refuse(workspace_dir, "look", format!("invalid --lines range {a}:{b}")));
            }
            let all: Vec<&str> = contents.lines().collect();
            let total = all.len();
            if a > total {
                (String::new(), format!("{path} lines {a}-{b} (file has {total} line(s); nothing in range)"))
            } else {
                let end = b.min(total);
                (all[a - 1..end].join("\n"), format!("{path} lines {a}-{end}"))
            }
        }
    };

    let mut printed = String::new();
    printed.push_str(&format!("==> {path} <==\n"));
    printed.push_str(&shown);
    if !shown.is_empty() && !shown.ends_with('\n') {
        printed.push('\n');
    }

    let entry = PendingEntry {
        kind: ObservationKind::Path,
        key,
        label,
        output: shown,
        world_root: world.root,
        world_state: world.state,
        captured_at: workspace::now_unix(),
        pattern: String::new(),
    };
    let mut buf = pending::load(workspace_dir)?;
    buf.push(entry);
    pending::save(workspace_dir, &buf)?;

    Ok(LookOutcome { printed })
}

